function climbStairs(n) {
  const ways = new Array(n + 1).fill(0);     // ways[i]: ways to stand on step i
  ways[0] = 1;
  ways[1] = 1;
  for (let i = 2; i <= n; i++) {
    ways[i] = ways[i - 1] + ways[i - 2];     // from one step below, or two
  }
  return ways[n];
}

